// Isolated interaction study. No audio, AI calls, user storage or production mutations.
const stations = [
  {name:'FIP', country:'Франция', tags:'Музыкальное радио', mark:'fip'},
  {name:'Radio Meuh', country:'Франция', tags:'Фанк · электроника', mark:'meuh'},
  {name:'Worldwide FM', country:'Великобритания', tags:'Джаз · электроника · музыка мира', mark:'ww'},
  {name:'SomaFM Groove Salad', country:'США', tags:'Эмбиент · даунтемпо', mark:'soma'},
  {name:'NTS Radio 1', country:'Великобритания', tags:'DJ-сеты · свободный формат', mark:'nts'},
  {name:'Radio Swiss Jazz', country:'Швейцария', tags:'Джаз', mark:'jazz'},
];
const routes = [
  {title:'От фанка к свободному эфиру',label:'Три поворота',copy:'Начните с Radio Meuh. Дальше — более широкий мир Worldwide FM и свободный формат NTS.',ids:[1,2,4],steps:['Начать с ритма','Расширить круг','Отпустить жанры']},
  {title:'Потише, но не скучнее',label:'Медленный маршрут',copy:'Джаз, даунтемпо и свободная музыкальная программа. Три способа снизить темп поиска.',ids:[5,3,0],steps:['Джазовый источник','Эмбиент и даунтемпо','Без одного жанра']},
  {title:'За пределы одного жанра',label:'Свободный выбор',copy:'Три станции с широким музыкальным форматом. Сравните их сами — эфир постоянно меняется.',ids:[0,4,2],steps:['Франция','Великобритания · NTS','Великобритания · Worldwide']},
];
let page='home',current=0,queue=[0,1,2],position=0,playing=false,started=false;
const saved=new Set();
const main=document.querySelector('#main'),dialog=document.querySelector('#detail');
let dialogTrigger=null,noticeTimer;
const row=(id)=>`<div class="station-row"><span class="station-art">${stations[id].mark}</span><div><strong>${stations[id].name}</strong><small>${stations[id].country} · ${stations[id].tags}</small></div><button class="icon" data-play="${id}" aria-label="Включить ${stations[id].name} в сценарии">▷</button></div>`;
function cards(){return routes.map((r,i)=>`<button class="direction" data-route="${i}"><small>${r.label}</small><strong>${r.title}</strong><span>3 станции · открыть маршрут</span><b aria-hidden="true">↗</b></button>`).join('');}
function showPage(next,focus=true){page=next;document.querySelectorAll('[data-page]').forEach(b=>{b.removeAttribute('aria-current');if(b.dataset.page===page)b.setAttribute('aria-current','page');});
if(page==='home') main.innerHTML=`<div class="intro"><h1>Слушать. Открывать.</h1><p>Можно просто слушать.<br>А можно узнать, что звучит за углом.</p></div><div class="start-grid"><section class="listen"><span class="eyebrow">Без долгого выбора</span><h2>Начнём с FIP.</h2><p>Франция · музыкальное радио.<br>Не зацепит — включим следующую.</p><div class="sun" aria-hidden="true"></div><div class="listen-controls"><button class="primary" data-action="start">▶ Включить радио</button></div><span class="fip" aria-hidden="true">fip</span></section><section class="feature"><span class="eyebrow">Если хочется покопаться</span><h2>Из фанка —<br>в свободный эфир.</h2><p>Фанк Radio Meuh → музыка мира Worldwide FM → свободный эфир NTS. С какой стороны зайдём?</p><div class="route-preview" aria-hidden="true"><span class="place">FR</span><span class="dash"></span><span class="place">GB</span><span class="dash"></span><span class="place">GB</span><small>Meuh → Worldwide → NTS</small></div><button class="secondary" data-route="0">Открыть маршрут ↗</button></section></div><div class="section-head"><h2>Куда свернём?</h2><button class="text-button" data-page="explore">Все направления</button></div><div class="directions">${cards()}</div><div class="lower"><section><div class="section-head"><h2>Ещё три повода послушать</h2></div><div class="station-list">${row(1)}${row(3)}${row(4)}</div></section><section class="lira-note"><div class="lira-label"><img src="/lira.webp" alt="">Лира · ваш музыкальный проводник</div><blockquote>«Оставим ритм,<br>но сменим направление?»</blockquote><p>Не нужно придумывать запрос. Выберите, что хочется изменить в музыке.</p><button class="text-button" data-page="lira">Выбрать поворот с Лирой ↗</button></section></div>`;
if(page==='explore') main.innerHTML=`<span class="eyebrow">Есть куда пойти дальше</span><h1 style="margin-top:14px">Следуйте за любопытством.</h1><p class="page-copy">У каждого направления — несколько источников и понятный следующий шаг. Просмотр не меняет текущую станцию.</p><div class="filters" role="group" aria-label="Направления"><button class="secondary" aria-pressed="true" data-filter="all">Все</button><button class="secondary" aria-pressed="false" data-filter="rhythm">Больше ритма</button><button class="secondary" aria-pressed="false" data-filter="calm">Спокойнее</button></div><div class="explore-grid">${cards()}</div><p class="note">Это ограниченный сценарий концепта. В приложении здесь нужны догрузка каталога и переходы на существующий Глобус, а не отдельный список вместо карты.</p>`;
if(page==='saved') main.innerHTML=`<span class="eyebrow">Собрано вами в этом концепте</span><h1 style="margin-top:14px">Моё</h1><p class="page-copy">Маршруты сохраняются только до перезагрузки этой страницы. Ваша настоящая медиатека не меняется.</p>${saved.size?`<div class="section-head"><h2>Сохранённые маршруты</h2></div><div class="directions">${[...saved].map(i=>`<button class="direction" data-route="${i}"><small>3 станции</small><strong>${routes[i].title}</strong><span>Открыть и продолжить ↗</span></button>`).join('')}</div>`:'<section class="empty"><h2>Первое открытие ещё впереди.</h2><p>Откройте маршрут и сохраните его, чтобы вернуться. Никакой регистрации для начала.</p><button class="primary" data-page="explore">Найти своё направление</button></section>'}`;
if(page==='lira') main.innerHTML=`<section class="lira-page"><div class="lira-label"><img src="/lira.webp" alt="">Лира · демонстрация сценария, не ответ AI</div><h1>Что хочется изменить<br>в следующем эфире?</h1><p class="page-copy">${started?`Отталкиваемся от ${stations[current].name}.`:'Можно начать без знания жанров и названий.'} Выбор ниже открывает предложение. Музыка переключается только отдельным нажатием.</p><div class="lira-choices"><button data-route="0">Больше движения <small>Фанк → музыка мира → свободный эфир</small></button><button data-route="1">Спокойнее, но с характером <small>Джаз и даунтемпо</small></button><button data-route="2">Вывести меня из привычного <small>Три источника без одного жанра</small></button></div><p class="note">В рабочей Лире остаётся свободный чат. Здесь проверяется более понятный вход в разговор; реплики и маршруты заданы заранее.</p></section>`;
window.scrollTo({top:0,behavior:'instant'});if(focus)main.focus({preventScroll:true});}
function notify(text){clearTimeout(noticeTimer);const n=document.querySelector('#notice');n.textContent=text;n.classList.add('visible');noticeTimer=setTimeout(()=>n.classList.remove('visible'),2300);}
function updatePlayer(){document.querySelector('.player').hidden=!started;document.querySelector('#station-name').textContent=stations[current].name;document.querySelector('.mini-art').textContent=stations[current].mark;document.querySelector('#station-state').textContent=playing?'Выбран эфир · сценарий без звука':'На паузе · сценарий без звука';document.querySelector('#toggle').textContent=playing?'Ⅱ':'▷';document.querySelector('#toggle').setAttribute('aria-label',playing?'Пауза в сценарии':'Продолжить сценарий');document.querySelector('#queue-count').textContent=queue.length;}
function openDialog(title,html){dialogTrigger=document.activeElement;dialog.setAttribute('aria-label',title);document.querySelector('#dialog-kicker').textContent=title;document.querySelector('#dialog-body').innerHTML=html;if(!dialog.open)dialog.showModal();}
function route(id){const r=routes[id];openDialog(r.label,`<h2>${r.title}</h2><p>${r.copy}</p>${r.ids.map((s,j)=>`<section class="path-card"><h3>${j+1}. ${r.steps[j]}</h3>${row(s)}</section>`).join('')}<div class="dialog-actions"><button class="primary" data-start-route="${id}">▶ Слушать маршрут</button><button class="secondary" data-save="${id}">${saved.has(id)?'✓ Сохранён':'♡ Сохранить маршрут'}</button></div><p class="note">Станции настоящие; порядок — редакционный пример. Звук в этом концепте не запускается.</p>`);}
function closeDialog(){dialog.close();}dialog.addEventListener('close',()=>dialogTrigger?.isConnected&&dialogTrigger.focus());
document.querySelector('#close').onclick=closeDialog;
document.querySelector('#layout').onclick=()=>{const top=document.body.classList.toggle('top-nav');document.querySelector('#layout').textContent=top?'Навигация: сверху':'Навигация: сбоку';document.querySelector('#layout').setAttribute('aria-pressed',String(top));};
document.querySelector('#toggle').onclick=()=>{playing=!playing;updatePlayer();};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.dataset.page){if(dialog.open)closeDialog();showPage(b.dataset.page);}
if(b.dataset.route!==undefined)route(Number(b.dataset.route));
if(b.dataset.play!==undefined){current=Number(b.dataset.play);position=queue.indexOf(current);if(position<0){queue=[current];position=0;}started=true;playing=true;updatePlayer();notify('Станция выбрана · демонстрация без звука');}
if(b.dataset.startRoute!==undefined){queue=[...routes[Number(b.dataset.startRoute)].ids];position=0;current=queue[0];started=true;playing=true;closeDialog();updatePlayer();notify('Маршрут выбран. «Дальше» сохраняет его порядок.');}
if(b.dataset.save!==undefined){const id=Number(b.dataset.save);saved.add(id);b.textContent='✓ Сохранён';notify('Сохранено в «Моё» этого концепта');}
if(b.dataset.filter){document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('.explore-grid [data-route]').forEach(x=>{x.hidden=b.dataset.filter==='rhythm'?x.dataset.route!=='0':b.dataset.filter==='calm'?x.dataset.route!=='1':false;});}
switch(b.dataset.action){case 'start':queue=[0,1,2];position=0;current=0;started=true;playing=true;updatePlayer();notify('Один тап — выбран эфир. Здесь демонстрация без звука.');break;
case 'next':if(position+1>=queue.length){notify('Маршрут закончился. Выберите новое направление.');return;}current=queue[++position];playing=true;updatePlayer();break;
case 'queue':openDialog('Текущий маршрут',`<h2>Что будет дальше</h2><p>Открытие очереди не меняет станцию.</p>${queue.map((s,j)=>`<div class="path-card"><h3>${j===position?'Сейчас':j<position?'Ранее':'Далее'}</h3>${row(s)}</div>`).join('')}`);break;
case 'about':openDialog('Статус: вариант для обсуждения',`<h2>Проверяем смысл, не только стекло.</h2><p>Этот концепт проверяет Главную: один шаг к эфиру и маршрут с понятным продолжением. Короткий боковой dock можно сравнить с верхним. На телефоне оба превращаются в нижний.</p><p class="note">Настоящие названия и теги — из существующей публичной выборки проекта. Нет аудио, AI, карты, облачного сохранения или изменения приложения. «Открытия» — пример группировки, не утверждённая замена Глобуса. Полноценная Лента и свободный чат сохраняются в рабочем продукте.</p>`);break;}});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();showPage('home');});
showPage('home',false);
